// Step 1: Pull raw input
let raw = $input.first().json.choices[0].message.content;
// Step 2: Forcefully remove anything between <think> and </think>
let cleaned = raw.replace(/<think>(.|\n)*?<\/think>/gi,
'').trim();
// Optional cleanup: remove leading/trailing blank lines
cleaned = cleaned.replace(/^\s+|\s+$/g, '');
// Done
return [
{
json: {
cleanedResponse: cleaned
}
}
];

// Récupère le contenu du premier item
const input = $input.first().json.message.content;

// On tolère les retours à la ligne réels (\n) ou échappés (\\n)

// Text Overlay
const textOverlayMatch = input.match(
  /Text\s*Overlay:\s*(.+?)(?:\r?\n|\\n)/s
);

// Video Script
const videoScriptMatch = input.match(
  /Video\s*Script:\s*(.+?)(?:\r?\n|\\n)Caption\s*Text:/s
);

// Caption Text (jusqu'à la fin)
const captionTextMatch = input.match(
  /Caption\s*Text:\s*(.+)/s
);

return [
  {
    json: {
      textOverlay:   textOverlayMatch   ? textOverlayMatch[1].trim()   : null,
      videoScript:   videoScriptMatch   ? videoScriptMatch[1].trim()   : null,
      captionText:   captionTextMatch   ? captionTextMatch[1].trim()   : null,
    }
  }
];

// Utility to create a random alphanumeric ID
function createUniqueId(length = 12) {
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let id = '';
  for (let i = 0; i < length; i++) {
    const randomIndex = Math.floor(Math.random() * characters.length);
    id += characters[randomIndex];
  }
  return id;
}

// Return the ID in the expected output structure
return [
  {
    json: {
      code: createUniqueId()
    }
  }
];

// Only YOUR chat may start this workflow, and only with a TikTok link. Every other message is ignored without an answer.
// The workflow spends your API credits and now publishes to your accounts, so it must never react to strangers.
const ALLOWED_CHAT_ID = 'REPLACE_WITH_YOUR_TELEGRAM_CHAT_ID'; // send any message to @userinfobot to learn your chat id
const msg = $json.message || {};
const chatId = msg.chat && msg.chat.id;
const text = String(msg.text || '').trim();
const isTikTok = /^https?:\/\/([a-z0-9-]+\.)?tiktok\.com\//i.test(text);
if (String(chatId) !== ALLOWED_CHAT_ID || !isTikTok) return [];
return [$input.first()];

// CEKIVA reads the video type from the file name and TikTok only takes .mp4 / .mov / .webm: name the file explicitly.
return $input.all().map((item) => {
  const b = item.binary && item.binary.data;
  if (!b) throw new Error('The final video could not be downloaded from JSON2Video.');
  b.fileName = 'video.mp4';
  b.mimeType = 'video/mp4';
  return item;
});

// CEKIVA publishing: one POST /v1/posts per network with the finished avatar video.
// X/Twitter is not here on purpose: CEKIVA retired that channel.
const CONFIG = {
  PLATFORMS: ['tiktok', 'instagram', 'youtube', 'facebook_page', 'linkedin', 'threads'], // CEKIVA platform ids. Remove the ones you did not connect.
  CLIENT_ID: '',      // optional: id of one of your CEKIVA client workspaces (GET https://cekiva.com/api/v1/clients); empty = your primary workspace
  PUBLISH_NOW: true,  // true = publish right away; false = publish at SCHEDULED_AT
  SCHEDULED_AT: '',   // ISO 8601 with a time zone, e.g. 2026-12-01T09:00:00Z (used only when PUBLISH_NOW is false)
  AI_LABEL: false,    // true = ask TikTok to mark the video "AI-generated". The poster's own decision: off by default.
};

const videoUrl = $input.first().json.url; // the CEKIVA-hosted copy of the final video
if (!videoUrl) throw new Error('CEKIVA did not return a video url.');
const caption = String($('Save Rewritten Video to Google Sheets').first().json.Caption || '').trim();
const scheduleAt = !CONFIG.PUBLISH_NOW && CONFIG.SCHEDULED_AT ? CONFIG.SCHEDULED_AT : null;

return CONFIG.PLATFORMS.map((platform) => {
  // The body of POST /v1/posts exactly as the CEKIVA API expects it.
  const request = { platforms: [platform], content: caption, image_url: videoUrl, media_urls: [videoUrl],
                    scheduled_for: scheduleAt || new Date().toISOString(), publish_now: !scheduleAt };
  if (CONFIG.CLIENT_ID) request.client_id = CONFIG.CLIENT_ID;
  if (CONFIG.AI_LABEL) request.ai_generated = true;
  return { json: { platform, request } };
});

// One uniform result row per platform, and a short text summary for Telegram.
const sent = $('Build CEKIVA posts').all();
const rows = $input.all().map((item, i) => {
  const r = item.json;
  const platform = sent[i] ? sent[i].json.platform : 'unknown';
  const body = r.body;
  const post = Array.isArray(body) ? body[0] : null;
  const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
  const status = Number(r.statusCode) || null;
  const ok = status !== null && status >= 200 && status < 300 && !!post;
  return {
    platform,
    result: ok ? 'Success' : 'Error',
    http_status: status,
    post_id: post ? post.id : null,
    post_status: post ? post.status : null,
    credits_charged: post ? post.credits_charged : null,
    error_code: err ? err.code : (r.error ? 'CEKIVA_UNREACHABLE' : null),
    error_message: err ? err.message : (r.error ? String(r.error.message || r.error).slice(0, 200) : (ok ? null : 'Unexpected response')),
    hint: err ? err.hint : null,
  };
});
const summary = rows.map((x) => (x.result === 'Success' ? '✅ ' + x.platform : '❌ ' + x.platform + ': ' + (x.error_code || '') + ' ' + (x.error_message || ''))).join('\n');
return [{ json: { rows, summary } }];
